import * as THREE from 'three';
import { describe, expect, it } from 'vitest';
import type { Hole } from '../courses/types';
import { HoleSceneBuilder } from './HoleSceneBuilder';

function makeHole(): Hole {
  return {
    id: 'test-hole',
    name: 'Test Hole',
    par: 3,
    spawn: { x: 0, y: 1, z: 0 },
    cup: { position: { x: 0, y: 0.2, z: 8 }, radius: 0.25, captureDepth: 0.4 },
    bounds: { min: { x: -5, y: 0, z: -5 }, max: { x: 5, y: 4, z: 12 } },
    surfaces: [
      {
        id: 'fairway',
        transform: { position: { x: 0, y: 0, z: 0 } },
        shape: 'box',
        size: { x: 6, y: 0.5, z: 20 },
        material: 'green',
      },
      {
        id: 'apron',
        transform: { position: { x: 0, y: 0, z: 9 }, scale: { x: 1, y: 2, z: 1 } },
        shape: 'box',
        size: { x: 4, y: 0.5, z: 4 },
        material: 'green',
      },
      {
        id: 'slope',
        transform: {
          position: { x: 0, y: 0.5, z: 4 },
          rotation: { x: 0, y: 0, z: 0.25881904510252074, w: 0.9659258262890683 },
        },
        shape: 'ramp',
        size: { x: 4, y: 0.4, z: 3 },
        material: 'wood',
      },
      {
        id: 'post',
        transform: { position: { x: 2, y: 0.5, z: 2 } },
        shape: 'cylinder',
        size: { x: 0.6, y: 1, z: 0.6 },
        material: 'stone',
      },
    ],
    obstacles: [
      {
        id: 'left-wall',
        type: 'wall',
        transform: { position: { x: -3, y: 0.5, z: 0 } },
        size: { x: 0.4, y: 1, z: 20 },
      },
      {
        id: 'spinner',
        type: 'spinner',
        transform: { position: { x: 0, y: 0.6, z: 6 } },
        size: { x: 3, y: 0.3, z: 0.3 },
        motion: { kind: 'rotate', axis: { x: 0, y: 1, z: 0 }, speed: 1.5 },
      },
    ],
  };
}

function meshNamed(group: THREE.Group, name: string): THREE.Mesh {
  const found = group.getObjectByName(name);
  if (!(found instanceof THREE.Mesh)) {
    throw new Error('mesh not found: ' + name);
  }
  return found;
}

describe('HoleSceneBuilder', () => {
  it('builds one mesh per surface and obstacle plus the cup marker', () => {
    const builder = new HoleSceneBuilder();
    const hole = makeHole();

    const result = builder.build(hole);

    expect(result.meshCount).toBe(hole.surfaces.length + hole.obstacles.length + 1);
    expect(result.group.children).toHaveLength(result.meshCount);
    expect(result.group.name).toBe('test-hole');
    expect(meshNamed(result.group, 'fairway').name).toBe('fairway');
    expect(meshNamed(result.group, 'spinner').name).toBe('spinner');
    builder.dispose();
  });

  it('adds a cup marker named after the hole and sized by the cup radius', () => {
    const builder = new HoleSceneBuilder();
    const hole = makeHole();

    const cup = meshNamed(builder.build(hole).group, 'test-hole-cup');

    expect(cup.position.toArray()).toEqual([0, 0.2, 8]);
    expect(cup.scale.x).toBeCloseTo(0.5);
    expect(cup.scale.z).toBeCloseTo(0.5);
    expect(cup.scale.y).toBeCloseTo(0.25);
    builder.dispose();
  });

  it('shares the cached geometry instances between separate builds', () => {
    const builder = new HoleSceneBuilder();
    const first = builder.build(makeHole());
    const second = builder.build(makeHole());

    const geometries = new Set<THREE.BufferGeometry>();
    for (const child of [...first.group.children, ...second.group.children]) {
      if (child instanceof THREE.Mesh) {
        geometries.add(child.geometry);
      }
    }

    expect(geometries.size).toBe(2);
    expect(meshNamed(first.group, 'fairway').geometry).toBe(meshNamed(second.group, 'fairway').geometry);
    expect(meshNamed(first.group, 'slope').geometry).toBe(meshNamed(first.group, 'fairway').geometry);
    expect(meshNamed(first.group, 'post').geometry).not.toBe(meshNamed(first.group, 'fairway').geometry);
    builder.dispose();
  });

  it('caches one material per surface material key and per obstacle type', () => {
    const builder = new HoleSceneBuilder();
    const first = builder.build(makeHole());
    const second = builder.build(makeHole());

    const fairway = meshNamed(first.group, 'fairway').material as THREE.MeshStandardMaterial;
    const apron = meshNamed(first.group, 'apron').material as THREE.MeshStandardMaterial;
    const slope = meshNamed(first.group, 'slope').material as THREE.MeshStandardMaterial;
    const wall = meshNamed(first.group, 'left-wall').material as THREE.MeshStandardMaterial;

    expect(apron).toBe(fairway);
    expect(meshNamed(second.group, 'fairway').material).toBe(fairway);
    expect(slope).not.toBe(fairway);
    expect(wall).not.toBe(fairway);
    expect(fairway.color.getHex()).toBe(0x4aa657);
    expect(slope.color.getHex()).toBe(0xa9713f);
    builder.dispose();
  });

  it('applies descriptor transforms and shadow flags', () => {
    const builder = new HoleSceneBuilder();
    const result = builder.build(makeHole());

    const fairway = meshNamed(result.group, 'fairway');
    const apron = meshNamed(result.group, 'apron');
    const slope = meshNamed(result.group, 'slope');
    const wall = meshNamed(result.group, 'left-wall');

    expect(fairway.scale.toArray()).toEqual([6, 0.5, 20]);
    expect(apron.scale.toArray()).toEqual([4, 1, 4]);
    expect(slope.quaternion.z).toBeCloseTo(0.25881904510252074);
    expect(fairway.castShadow).toBe(false);
    expect(fairway.receiveShadow).toBe(true);
    expect(wall.castShadow).toBe(true);
    builder.dispose();
  });

  it('empties the group on result dispose without breaking later builds', () => {
    const builder = new HoleSceneBuilder();
    const result = builder.build(makeHole());

    result.dispose();

    expect(result.group.children).toHaveLength(0);
    const rebuilt = builder.build(makeHole());
    expect(rebuilt.group.children).toHaveLength(rebuilt.meshCount);
    builder.dispose();
  });
});
